#!/bin/sh
# sk-v27 LW3.AUDIT-CLEAN mutant reads (RULINGS 2026-11-14k CLEAN-PROFILE): each Phase 3b1 unit's mutant,
# re-made on the integration tip as a worktree edit (no ref moved), read once by the unit's own falsifier,
# then restored. A generator mutant is regenerated by `cargo xtask regen` (ax-iter) and the generated
# diff is recorded, so the read is proved to run the mutant library; the touched library's hash is
# printed before and after each mutant (tgt-clean.sh hash). One row per mutant in $L/mutants.tsv:
# unit, falsifier rc (non-zero = the mutant is refused), read.
# Usage: mutants.sh <worktree> <log dir> [unit...]
set -u
W=$1; L=$2; shift 2; mkdir -p "$L"
export CARGO_INCREMENTAL=0 CARGO_TARGET_DIR=$HOME/.dev-logs/bbnf-lockstep/lw3/target-bbnf-lang
export BBNF_CORPUS_DIR=$HOME/.dev-logs/bbnf-lockstep/lw3/s7-spine/corpus
export BBNF_ORACLE_CACHE=$HOME/.dev-logs/bbnf-lockstep/lw3/s5b-oracle/oracle-cache
E=$W/restart/skinny/tranches/sk-v27/evidence; S=$E/LW3.AUDIT/tgt-clean.sh; A=$E/LW3.AUDIT
cd "$W" || exit 2
row() { printf '%s\t%s\t%s\n' "$1" "$2" "$3" >> "$L/mutants.tsv"; }
clean_tree() { git checkout -q -- crates xtask 2>/dev/null; rm -f crates/ir/tests/stale0_mutant.rs;
  d=$(git status --short | grep -vc '^??'); echo "restored dirty=$d" >> "$L/$1.log"; }
hashes() { for p in dev ax-iter; do $S hash $p bbnf bbnf_ir gorgeous xtask; done | sed "s/^/$1 /" >> "$L/hashes.txt"; }
regen() { cargo xtask regen > "$L/$1.regen.log" 2>&1; echo "regen rc=$? generated: $(git diff --stat -- crates/core/src/grammar/generated crates/gorgeous | tail -1)" >> "$L/$1.log"; }
want=${*:-TREE-1 PERF-1c COMP-6-lattice COMP-6-verifier STALE-0 COMP-5a S3c-PP-css S3c-PP-ebnf S3c-PP-bbnf PERF-1d ORC2-WS-C}
for u in $want; do
  : > "$L/$u.log"; hashes "$u:before"
  case $u in
  TREE-1) git apply $E/LW3.P3A/logs/tree1-mutant.diff
    sh $E/LW3.P3A/tree_write_check.sh "$W" "$L/tree1" >> "$L/$u.log" 2>&1; rc=$?; r=$(cat $L/tree1/result.txt) ;;
  PERF-1c) printf '\npub enum KernelShape {}\n' >> crates/ir/src/passes/recognizers/mod.rs
    export GIT_INDEX_FILE=$L/perf1c.idx; git read-tree HEAD; git update-index crates/ir/src/passes/recognizers/mod.rs
    C=$(git commit-tree $(git write-tree) -p HEAD -m "LW3.AUDIT-CLEAN PERF-1c mutant (unreferenced)"); unset GIT_INDEX_FILE; rm -f $L/perf1c.idx
    PT=$(grep -oE 'parse_that +=.*rev = "[0-9a-f]+"' Cargo.toml | grep -oE '[0-9a-f]{40}')
    sh $E/LW3.PERF/perf1c/perf1c_check.sh "$W" $C $HOME/Programming/parse-that $PT >> "$L/$u.log" 2>&1; rc=$?; r="$(grep -c : $L/$u.log) files listed (commit $C)" ;;
  COMP-6-lattice) git apply $E/LW3.COMP/comp6/logs/disp-mutant.diff
    sh $E/LW3.COMP/comp6/laws.sh "$W" "$L/comp6-laws" >> "$L/$u.log" 2>&1; rc=$?; r=$(cat $L/comp6-laws/result.txt) ;;
  COMP-6-verifier) sed -i '' 's/Op::RuleRef(rule) => ensure(\*rule < rules, stage, Law::RuleInRange, index)?,/Op::RuleRef(_rule) => {}/' crates/core/src/compiler/verify/laws.rs
    git diff --stat >> "$L/$u.log"
    sh $E/LW3.COMP/comp6/verify/verify.sh "$W" "$L/comp6-verify" >> "$L/$u.log" 2>&1; rc=$?; r=$(cat $L/comp6-verify/result.txt) ;;
  STALE-0) printf '#[test]\nfn mutant() {}\n' > crates/ir/tests/stale0_mutant.rs
    cargo nextest run -p bbnf --locked --no-fail-fast --retries 0 --test w3_replay_public_contract \
      -E 'test(cargo_graph_build_feature_surfaces_and_generated_products_are_closed)' >> "$L/$u.log" 2>&1; rc=$?
    r="$(grep -E '^ +Summary' $L/$u.log | sed 's/^ *//') $(grep -m1 -oE 'left: \"[0-9a-f]{8}' $L/$u.log)" ;;
  COMP-5a) git apply $E/LW3.COMP/comp5a/logs/mutant.diff
    cargo nextest run -p bbnf --locked --no-fail-fast --retries 0 --test no_grammar_name_branch --test plan_contract >> "$L/$u.log" 2>&1; rc=$?
    r="$(grep -E '^ +Summary' $L/$u.log | sed 's/^ *//') $(grep -m1 -oE 'shapes/mod.rs:[0-9]+' $L/$u.log)" ;;
  S3c-PP-css) git apply --include='crates/core/src/backend/*' $E/LW3.PP/s3c/logs/mutant-css.diff; regen $u
    cargo test -p gorgeous --features css-grammar --test css css_ws_leaves_are_trivia_so_formatting_is_idempotent >> "$L/$u.log" 2>&1; rc=$?
    r="$(grep -E '^test result' $L/$u.log | tail -1) $(grep 'regen rc' $L/$u.log)" ;;
  S3c-PP-ebnf) git apply --include='crates/core/src/backend/*' $E/LW3.PP/s3c/logs/mutant-ebnf.diff; regen $u
    { cargo test -p gorgeous --features ebnf-grammar --test ebnf -- ebnf_prettify_keeps_every_rule_and_terminal test_prettify_multi_rule; a=$?
      cargo test -p bbnf --test ebnf_prettify prettify_multi_rule; b=$?; echo "ebnf=$a core=$b"; } >> "$L/$u.log" 2>&1
    r="$(tail -1 $L/$u.log) $(grep 'regen rc' $L/$u.log)"; case "$(tail -1 $L/$u.log)" in "ebnf=0 core=0") rc=0;; *) rc=1;; esac ;;
  S3c-PP-bbnf) python3 -I - crates/core/src/backend/rust/emitter/prettify/grammar.rs <<'PY'
import sys; p=sys.argv[1]; s=open(p).read(); t="            __builder.break_parent();\n"
assert s.count(t)==1, s.count(t); open(p,"w").write(s.replace(t,""))
PY
    regen $u
    cargo test -p gorgeous --features bbnf-grammar --test bbnf >> "$L/$u.log" 2>&1; rc=$?
    r="$(grep -E '^test result' $L/$u.log | tail -1) $(grep 'regen rc' $L/$u.log)" ;;
  PERF-1d) python3 -I - crates/core/src/backend/rust/emitter/shapes/dispatcher/support.rs <<'PY'
import sys; p=sys.argv[1]; s=open(p).read(); t="                ::parse_that::scan::find_quote_or_backslash(bytes)"
assert s.count(t)==1; open(p,"w").write(s.replace(t,"                let _ = ::core::arch::aarch64::vdupq_n_u8;\n"+t))
PY
    regen $u
    n=$(git grep -l 'core::arch\|std::simd' -- crates/core/src/grammar/generated | wc -l | tr -d ' ')
    echo "generated files naming core::arch: $n" >> "$L/$u.log"; [ "$n" -eq 0 ]; rc=$?; r="generated files naming core::arch=$n $(grep 'regen rc' $L/$u.log)" ;;
  ORC2-WS-C) git apply -R $E/LW3.ORC/orc2-ws-c/cure-generator.diff; regen $u
    cargo nextest run --cargo-profile ax-iter -p bbnf --locked --test rb_root_whitespace --run-ignored all --no-fail-fast >> "$L/$u.log" 2>&1; rc=$?
    r="$(grep -E '^ +Summary' $L/$u.log | sed 's/^ *//') $(grep 'regen rc' $L/$u.log)" ;;
  esac
  hashes "$u:mutant"; clean_tree $u; row "$u" "$rc" "$r"
done
cat "$L/mutants.tsv"
